  // hdriModule 已下放给 lightModule.init 按需 register（避免 h5 显式 use + lightModule.init register 重复触发 unregister 副作用，对齐 harness SceneViewer.vue）
  // unified-shape-trigger-ecs 阶段二：手动装配 Trigger 调试入口（triggerDebug=1 门控，见 onMounted 场景就绪处）
  installShapeTriggerDebug,
  diagnoseShapeTriggerDebug,
  watchShapeTriggerDebug,
  teleportShapeTriggerActor,
  subscribeTrigger,
} from '@tencent/viewer-sdk';
import type { EngineContext, URLCharacterParams, ConfigManager } from '@tencent/viewer-sdk';
import { provideEngineContext } from '../../composables/useEngineContext';
import { isWeixin } from '../../utils';
import { checkOpenidWhitelist } from '../../utils/util';
import { hasNewRouteParams, buildURLParamsFromRoute, getShowDebugViewerFromRoute, parseURLParamsFromQuery, getExtraParamsFromRoute, parseExtraParamsFromQuery, resolveSceneUrlFromSiteUri } from '../../utils/route-params';


// 带类型的角色模型信息（扩展 CharacterModelInfo）
type CharacterType = 'humanoid' | 'non-humanoid' | 'dynamic';
interface TypedCharacterModelInfo extends CharacterModelInfo {
  type?: CharacterType;
}

// DOM 引用
const containerRef = ref<HTMLDivElement>();
const virtualJoystickRef = ref<InstanceType<typeof VirtualJoystick>>();
const interactionRef = ref<DialogType>();
const fileInputRef = ref<HTMLInputElement>();
const modelSelectorContentRef = ref<HTMLDivElement>(); // 模型选择器内容区域ref
// viewerSDK 实例
const viewerSDK = new ViewerSDK();

// 读取路由参数（params 优先，兼容旧的 URL query 方式）
const route = useRoute();

// EngineContext 注入：viewerSDK.init() 是异步的，ctx 在 onMounted 末尾才有值；
// 这里在 setup 顶层先 provide 一个 Ref<undefined>，子组件（DebugPanel 内的
// useHdriParams / useSkyParams / useCloudParams）通过 useEngineContext / useEngineContextGetter
// inject 同一个 Ref 引用，ctx 就绪后所有消费者自动响应。
// 对齐 thirdroom 的 useMainThreadContext 写法（src/ui/hooks/useMainThread.ts）。
const engineCtxRef = ref<EngineContext | undefined>(undefined);
provideEngineContext(engineCtxRef);

// thirdroom input 收官（配套 SDK sdk-input-bindings 删除）：H5 层自订阅句柄集合
const inputUnsubscribes = ref<Array<() => void>>([]);

// 本地 UI 状态（用于模型选择器等本地功能）
const localUIState = ref({
  showModelSelector: false,
  selectedModelId: LocalModelConfig.default,
  isCharacterLoading: false, // 角色加载中状态，防止重复切换
});

// 用于触发 Vue 响应式更新的状态
// v20260807（Breaking · UIModule 收编 toast）：`showToast: boolean` / `toastMessage: string`
// 两字段从 pluginUIState 移除 —— toast 由 uiModule CSS2D overlay 直挂 DOM，Vue 不再感知 toast 状态。
// 外部若有 `uiState.showToast` / `uiState.toastMessage` 读取需同步删除。
const pluginUIState = ref<{
  isOrbitControlActive: boolean;
  isOrbitControlManuallyActivated: boolean;
  isFullscreen: boolean;
  currentModelId: string;
  selectedModelId: string;
  isJumping: boolean;
  isSceneReady: boolean;
  showAudioPanel: boolean;
}>({
  isOrbitControlActive: false,
  isOrbitControlManuallyActivated: false,
  isFullscreen: false,
  currentModelId: LocalModelConfig.default,
  selectedModelId: LocalModelConfig.default,
  isJumping: false,
  isSceneReady: false,
  showAudioPanel: false,
});

// 从 viewerSDK 获取的响应式状态
const uiState = computed(() => ({
  ...pluginUIState.value,
  showModelSelector: localUIState.value.showModelSelector,
  selectedModelId: localUIState.value.selectedModelId,
  isCharacterLoading: localUIState.value.isCharacterLoading,
}));

// 计算属性：是否可以切换角色（场景就绪且角色未在加载中）
const canSwitchCharacter = computed(() => pluginUIState.value.isSceneReady && !localUIState.value.isCharacterLoading);

// 摄像机灵敏度（用于 DebugPanel）
const pluginCameraSensitivity = ref(0.003);
const cameraSensitivity = computed(() => pluginCameraSensitivity.value);

// 标记 viewerSDK 是否已初始化（用于触发 computed 重新计算）
const isPluginInitialized = ref(false);

// 是否展示调试 UI（新格式：route params/segments | 老格式：URL query 回退）
const showDebugViewer = ref(getShowDebugViewerFromRoute(route));

// 子面板显隐由本页统一维护，DebugPanel 只负责触发切换事件。
const showEnvironmentPanel = ref(false);
const showScenePanel = ref(false);
const showPerformancePanel = ref(false);
type SidePanelKey = 'environment' | 'scene' | 'performance';
const panelOrder = ref<SidePanelKey[]>([]);

function updatePanelOrder(panel: SidePanelKey, visible: boolean) {
  const index = panelOrder.value.indexOf(panel);
  if (visible && index === -1) {
    panelOrder.value.push(panel);
  } else if (!visible && index !== -1) {
    panelOrder.value.splice(index, 1);
  }
}

watch(showEnvironmentPanel, (visible) => updatePanelOrder('environment', visible));
watch(showScenePanel, (visible) => updatePanelOrder('scene', visible));
watch(showPerformancePanel, (visible) => updatePanelOrder('performance', visible));

// v20260904：DebugPanel 关闭按钮的连带处理。
// 主体面板关闭时同步把环境/场景/性能统计三个子面板一起关掉，
// 避免「DebugPanel 没了但子面板还浮在画面上」的状态错位。
function closeAllSidePanels(): void {
  showEnvironmentPanel.value = false;
  showScenePanel.value = false;
  showPerformancePanel.value = false;
}

// OpenID 是否命中「二次分享」白名单（与 showDebugViewer 解耦的独立信号源，
// 模板 v-if 用「showDebugViewer || isOpenidWhitelisted」做或运算放行渲染）
const isOpenidWhitelisted = ref(false);

// v20260728（Breaking · SceneManager 瘦身第十刀）：`viewerSDK.getDebugManager()` public API 已删除。
// DebugPanel 内部改由 `useEngineContextGetter()` inject EngineContext + ctx-based debug helpers
// （debugGetWorldOffset / debugGetPerformanceStats / debugGetPhysicsInfo / debugGetDebugConfig）实现，
// 父组件不再需要 debugManager computed / prop 转发。

// v20260813（SDK 门面收敛 · sceneManager prop 死代码整体清理）：SceneManager 类整体废除后
//   `viewerSDK.getSceneManager()` public API 已删除；原过渡兼容层 `sceneManager` computed
//   恒返回 undefined 亦一并清除。DebugPanel 内部通过 useEngineContext() 直接观察
//   EngineContext Ref 完成 HDRI / Sky / TOD / PostProcessing 初始化，父组件不再需要
//   sceneManager computed / prop 转发。

// 获取正确的资源路径
function getAssetPath(path: string): string {
  if (import.meta.env.DEV) {
    return path.startsWith('/') ? path : `/${path}`;
  }
  return path.startsWith('/') ? `.${path}` : path;
}

// 可用的模型列表
const availableModels = ref<TypedCharacterModelInfo[]>(
  LocalModelConfig.models.map((model) => ({
    ...model,
    imagePath: getAssetPath(model.imagePath),
  })),
);

// 人形角色列表
const humanoidModels = computed(() =>
  availableModels.value.filter((model) => model.type === 'humanoid' || (!model.type && LocalModelConfig.humanoidModels.some((h) => h.id === model.id))),
);

// 非人形角色列表
const nonHumanoidModels = computed(() =>
  availableModels.value.filter((model) => model.type === 'non-humanoid' || (!model.type && LocalModelConfig.nonHumanoidModels.some((n) => n.id === model.id))),
);

// 动态角色列表（用户上传或URL传入的）
const dynamicModels = computed(() =>
  availableModels.value.filter((model) => model.type === 'dynamic' || model.id.startsWith('dynamic_') || model.id.startsWith('local_')),
);

// 添加动态角色到模型列表
function addDynamicCharacterToModelList(characterInfo: CharacterModelInfo) {
  // 检查是否是预设角色（来自 LocalModelConfig.models）
  const isPresetCharacter = LocalModelConfig.models.some((model) => model.id === characterInfo.id);

  if (isPresetCharacter) {
    // 预设角色：不需要添加到列表，只需更新选中状态
    console.log(`🎭 使用预设角色: ${characterInfo.name} (ID: ${characterInfo.id})`);
    localUIState.value.selectedModelId = characterInfo.id;
    return;
  }

  // 动态角色：使用 dynamic_ 前缀
  const modelId = `dynamic_${characterInfo.name}`;

  const existingModel = availableModels.value.find((model) => model.id === modelId);
  if (existingModel) {
    console.log(`🔄 动态模型已存在: ${characterInfo.name}`);
    localUIState.value.selectedModelId = modelId;
    return;
  }

  const newModel: TypedCharacterModelInfo = {
    id: modelId,
    name: characterInfo.name,
    describe: characterInfo.describe || '动态加载的角色模型',
    modelFilePath: characterInfo.modelFilePath,
    imagePath: characterInfo.imagePath ||
      'data:image/svg+xml;base64,',
    transform: characterInfo.transform,
    anim: characterInfo.anim,
    type: 'dynamic',
  };

  availableModels.value.unshift(newModel);
  localUIState.value.selectedModelId = modelId;

  console.log(`✅ 动态角色已添加到模型列表: ${characterInfo.name} (${modelId})`);
}

onMounted(async () => {
  if (!containerRef.value) return;

  // OpenID 白名单校验：与 metaverse/debug-panel.ts 对齐——
  // 即使 URL 没有 showDebugViewer=true，命中白名单的用户也直接放行 DebugPanel 渲染，
  // 让授权用户看到「允许二次分享」开关。fire-and-forget，不阻塞首屏 / 引擎初始化。
  // 使用独立的 isOpenidWhitelisted 信号源（不污染 showDebugViewer 的语义），
  // 模板侧通过 v-if="showDebugViewer || isOpenidWhitelisted" 做或运算。
  void checkOpenidWhitelist().then((hit) => {
    if (hit) {
      isOpenidWhitelisted.value = true;
      console.log('[SceneViewer] OpenID 命中白名单，放行 DebugPanel 渲染');
    }
  });

  // 微信浏览器/小程序 webview 环境：动态加载 jweixin.js（默认 CDN：腾讯云 COS）。
  // 加载后 window.wx 可用，useZoneInteraction 中 wx.miniProgram.postMessage / navigateTo 才能正常工作。
  // 与原 3d-gaussian-splatting-viewer Metaverse.vue 行为对齐。
  if (isWeixin()) {
    getPlatformAdapter().wechat.initWxSdk('./jweixin.js');
  }

  // 从 route.params 构建 URL 参数（新格式），无 params 时回退到 URL query（兼容老链接 ?key=value）
  const urlParams: URLCharacterParams = hasNewRouteParams(route)
    ? buildURLParamsFromRoute(route)
    : parseURLParamsFromQuery();
  const extraParams = hasNewRouteParams(route)
    ? getExtraParamsFromRoute(route)
    : parseExtraParamsFromQuery();
  console.log('路由 params:', urlParams);

  // [E2E 渲染巡检] gated 就绪信号注入：仅当 URL hash 含 renderTest=1 时才建立信号对象。
  // probe 端（render-probe.mjs）通过 page.waitForFunction 轮询 window.__SCENE_RENDER_TEST__.ready，
  // isSceneReady watch（下方 line ~820）内置位 ready=true。
  // gate 保证生产行为零变化（无 renderTest=1 时信号对象不存在，watch 内 if(testSignal) 判空跳过）。
  // 必须在 viewerSDK.init() 之前建立，否则 init 抛错时 error 兜底无法捕获。
  if (/[?&]renderTest=1(?:&|$)/.test(window.location.hash)) {
    (window as unknown as { __SCENE_RENDER_TEST__?: { ready: boolean; sceneUrl?: string; error?: string } })
      .__SCENE_RENDER_TEST__ = { ready: false, sceneUrl: urlParams.sceneUrl };
    // error / unhandledrejection 兜底：让 probe 端 page.evaluate(() => ...?.error) 能读到 init 异常
    window.addEventListener('error', (e) => {
      const sig = (window as unknown as { __SCENE_RENDER_TEST__?: { error?: string } }).__SCENE_RENDER_TEST__;
      if (sig && !sig.error) sig.error = String(e.message ?? e.error ?? 'unknown error');
    });
    window.addEventListener('unhandledrejection', (e) => {
      const sig = (window as unknown as { __SCENE_RENDER_TEST__?: { error?: string } }).__SCENE_RENDER_TEST__;
      if (sig && !sig.error) sig.error = String(e.reason ?? 'unhandled rejection');
    });
  }

  // 如果 sceneUrl 是 siteUri（.site 结尾），从场景配置中解析真实 modelUrl
  if (urlParams.sceneUrl?.endsWith('.site')) {
    urlParams.sceneUrl = await resolveSceneUrlFromSiteUri(urlParams.sceneUrl);
    console.log('siteUri 解析结果:', urlParams.sceneUrl);
  }

  const characterInfo = viewerSDK.buildCharacterInfoFromURLParams(urlParams);

  console.log('角色信息:', characterInfo);

  // 初始化 viewerSDK
  await viewerSDK.init({
    container: containerRef.value,
    sceneUrl: urlParams.sceneUrl,
    characterInfo,
    thirdPartyUrl: urlParams.thirdPartyUrl,
    defaultOperationMode: 'dual',
    ...extraParams,
    enableCliffDetection: true,
    cliffDetectionMode: 'slide',
    cliffDetectionConfig: {
      enabled: CLIFF_DETECTION_CONFIG.ENABLED,
      checkDistance: CLIFF_DETECTION_CONFIG.CHECK_DISTANCE,
      maxFallDistance: CLIFF_DETECTION_CONFIG.MAX_FALL_DISTANCE,
      safetyMargin: CLIFF_DETECTION_CONFIG.SAFETY_MARGIN,
    },
    interactionRef: interactionRef.value!,
    // Wave-1 (2026-07 pluggable-refactor)：SDK v2.2.0 后 npc/debug 从必装链摘除，此处显式补装保持行为等价
    // 注：animationModule 已于 20260714 中央化并重回 SDK 必装链（character/npc 硬依赖），无需在此补装
    // hdriModule 由 lightModule.init 内按 lighting.hdri 字段决策 register（对齐 harness SceneViewer.vue 同款，
    //   避免 h5 显式 use + lightModule.init register 重复触发 web-engine.register 的 unregister+dispose 副作用，
    //   该副作用会在 dispose→重新 init 之间的窗口期清空 scene.environment 导致 PBR 物体受光偏暗）
    extraModules: [lightModule, audioModule, npcManagerModule, npcSystemModule, debugModule, gs4dModule, listenerModule],
    hideDebugViewer: !showDebugViewer.value,
  });

  // 监听 viewerSDK 状态变化，同步到 Vue 响应式系统
  viewerSDK.onUIStateChange((newState) => {
    Object.assign(pluginUIState.value, newState);
  });

  viewerSDK.onCameraSensitivityChange((newValue) => {
    pluginCameraSensitivity.value = newValue;
  });

  // 初始化状态同步
  Object.assign(pluginUIState.value, viewerSDK.uiState);
  pluginCameraSensitivity.value = viewerSDK.cameraSensitivity;

  // 注入 EngineContext：viewerSDK.init() 完成后 webEngine.ctx 才存在，
  // 此时把 ctx 写入 provide 的 Ref，DebugPanel 子树内 useEngineContext / useEngineContextGetter
  // 立即拿到最新值。
  // ⚠️ 必须在 isPluginInitialized 之前：isPluginInitialized 会触发 DebugPanel 的
  // sceneManager watcher + onSceneReady 回调同步执行 init 函数（HDRI/Sky/TOD/后处理），
  // 这些 init 内部通过 getCtx() 读取 engineCtxRef.value，若尚未赋值则 available 一直为 false
  // 导致 Checkbox 不可见。
  // v20260813：SDK 门面收敛，改走 viewerSDK.getContext() 获取 EngineContext（不再暴露 WebEngine）
  engineCtxRef.value = viewerSDK.getContext() ?? undefined;

  // 进入场景后，将页面 title 更新为 ProjectConfig.name
  // v20260813（thirdroom 路径 3）：bootstrap 内就近复用 engineCtxRef.value，避免二次访问 sdk 门面
  // configManager cast 到 ConfigManager 实例：EngineContext.configManager 类型为 ConfigManagerLike
  // 门面（不含 getConfig 方法），运行时实际是 ConfigManager 实例（对齐 memory SOP：configManager 门面访问模式）
  const configManager = engineCtxRef.value?.configManager as ConfigManager | undefined;
  const projectName = configManager?.getConfig()?.name;
  if (projectName) {
    document.title = `${projectName} @ Web Wide World`;
  }

  // 进入场景后清空转发卡片的描述：保留 meta 标签并写入不可见但非空的盲文空白，
  // 避免分享组件在 description 缺失或为空时回退抓取页面正文/URL。
  document
    .querySelectorAll('meta[name="description"], meta[property="og:description"], meta[name="twitter:description"]')
    .forEach((el) => el.setAttribute('content', '\u2800'));

  // 标记插件已初始化，触发相关 computed 重新计算
  isPluginInitialized.value = true;

  // thirdroom input 收官（配套 SDK sdk-input-bindings.ts 删除）：H5 层自订阅
  // - Character.MoveLeft/MoveRight 沿：驱动 VirtualJoystick 弧线动画
  // - windowBlurred 上升沿：驱动 VirtualJoystick 强制重置
  // - 悬崖检测状态变更：展示 toast
  const ctx = engineCtxRef.value;
  if (ctx) {
    // v6.0.0：subscribeActionEdge / subscribeInputReset 改走 inputModule.api
    const inputApi = getModule(ctx, inputModule).api;
    inputUnsubscribes.value.push(
      inputApi.subscribeActionEdge(ctx, 'Character.MoveLeft', 'pressed', () => {
        virtualJoystickRef.value?.showEdgeArcFromKeyboard('left', false);
      }),
      inputApi.subscribeActionEdge(ctx, 'Character.MoveLeft', 'released', () => {
        virtualJoystickRef.value?.startEdgeArcFadeOut();
      }),
      inputApi.subscribeActionEdge(ctx, 'Character.MoveRight', 'pressed', () => {
        virtualJoystickRef.value?.showEdgeArcFromKeyboard('right', false);
      }),
      inputApi.subscribeActionEdge(ctx, 'Character.MoveRight', 'released', () => {
        virtualJoystickRef.value?.startEdgeArcFadeOut();
      }),
      // v6.0.0：onCliffDetectionChange 改走 characterModule.api（顶层 export 已从 SDK barrel 摘除）
      getModule(ctx, characterModule).api.onCliffDetectionChange(ctx, (status) => {
        viewerSDK?.showToast(`悬崖检测: ${status.enabled ? '启用' : '禁用'}`);
      }),
      inputApi.subscribeInputReset(ctx, () => {
        virtualJoystickRef.value?.forceReset();
      }),
    );
  }

  // 开始动画循环
  viewerSDK.animate();
});

// 监听场景就绪状态，在场景就绪时处理动态角色
watch(
  () => pluginUIState.value.isSceneReady,
  (isReady) => {
    if (isReady) {
      // [E2E 渲染巡检] gated 就绪信号置位：仅当此前 renderTest=1 已建立信号对象时才写入。
      const testSignal = (window as unknown as { __SCENE_RENDER_TEST__?: { ready: boolean } })
        .__SCENE_RENDER_TEST__;
      if (testSignal) testSignal.ready = true;

      // 如果有动态角色信息，添加到可用模型列表中
      const dynamicCharacterInfo = viewerSDK.getCharacterInfo();
      if (dynamicCharacterInfo) {
        addDynamicCharacterToModelList(dynamicCharacterInfo);
      }
      console.log('🎭 场景就绪，当前模型ID:', viewerSDK.uiState.currentModelId);

      // [unified-shape-trigger-ecs 阶段二调试] triggerDebug=1 门控：暴露调试入口并**默认自动装配**。
      // 用法：URL hash 带 triggerDebug=1 加载场景，场景就绪后自动注册全部 interactionZones
      //   shape 为 Trigger + 角色 actor + 通配订阅，直接走位即可在控制台观察 enter/exit；
      //   无需手动执行 window.__triggerDebug.install()。
      //   window.__triggerDebug.uninstall() → 注销全部 Trigger/Actor/订阅
      //   window.__triggerDebug.watch()     → 额外每帧采样（相交/位置），stopWatch() 停止
      // 与 renderTest=1 同款门控惯例：生产 URL 无该参数时 window.__triggerDebug 不存在，零副作用。
      if (/[?&]triggerDebug=1(?:&|$)/.test(window.location.hash)) {
        const triggerCtx = engineCtxRef.value;
        // configManager 在 onMounted 局部作用域，此处从 ctx 直接取（对齐 useEngineContextGetter 惯例）
        const triggerConfig = (engineCtxRef.value?.configManager as ConfigManager | undefined)?.getConfig();
        const triggerDebugApi = {
          ctx: triggerCtx,
          config: triggerConfig,
          uninstall: undefined as (() => void) | undefined,
          // 内部存储 watch 停止句柄（与下方 stopWatch 方法区分，避免同名覆盖）
          _stopWatch: undefined as (() => void) | undefined,
          // 内部存储 stay 节流订阅退订句柄（installShapeTriggerDebug 之外单独订阅，验证 stayIntervalMs）
          _unsubStay: undefined as (() => void) | undefined,
          install: () => {
            if (!triggerCtx || !triggerConfig) {
              console.warn('[trigger-debug] ctx 或 config 未就绪，场景加载完成后重试');
              return;
            }
            // 幂等保护：已装配时提示先 uninstall，避免重复注册 Trigger/Actor
            if (triggerDebugApi.uninstall) {
              console.warn('[trigger-debug] 已自动装配，如需重新注册先执行 window.__triggerDebug.uninstall()');
              return;
            }
            const uninstall = installShapeTriggerDebug(triggerCtx, triggerConfig, {
              logPrefix: '[trigger-debug]',
            });

            // 阶段二调试验证：subscribeTrigger 订阅粒度——stay 按 500ms 节流打印（防刷屏）
            triggerDebugApi._unsubStay?.();
            triggerDebugApi._unsubStay = subscribeTrigger(
              triggerCtx,
              '*',
              (event) => {
                console.log(`[my-stay] ${event.phase} trigger=${event.triggerId} shape=${event.shapeType}`);
              },
              { stayIntervalMs: 500 },
            );
            // 包裹 uninstall：连同 installShapeTriggerDebug 的退订一起释放 stay 订阅
            triggerDebugApi.uninstall = () => {
              uninstall();
              triggerDebugApi._unsubStay?.();
              triggerDebugApi._unsubStay = undefined;
              // 关键：释放句柄，否则 install() 的幂等保护误判"已装配"，无法再次 install
              triggerDebugApi.uninstall = undefined;
            };
          },
          diagnose: () => {
            if (!triggerCtx) {
              console.warn('[trigger-debug] ctx 未就绪');
              return;
            }
            diagnoseShapeTriggerDebug(triggerCtx, '[trigger-debug]');
          },
          watch: () => {
            if (!triggerCtx) {
              console.warn('[trigger-debug] ctx 未就绪');
              return;
            }
            if (triggerDebugApi._stopWatch) {
              console.warn('[trigger-debug] watch 已在运行，先 stopWatch');
              return;
            }
            triggerDebugApi._stopWatch = watchShapeTriggerDebug(triggerCtx, '[trigger-debug]');
            console.log('[trigger-debug] watch 已启动，走位观察；执行 window.__triggerDebug.stopWatch() 停止');
          },
          stopWatch: () => {
            triggerDebugApi._stopWatch?.();
            triggerDebugApi._stopWatch = undefined;
          },
          teleportToZone: (zoneId: string) => {
            if (!triggerCtx) {
              console.warn('[trigger-debug] ctx 未就绪');
              return;
            }
            teleportShapeTriggerActor(triggerCtx, zoneId, '[trigger-debug]');
          },
        };
        (window as unknown as { __triggerDebug?: typeof triggerDebugApi }).__triggerDebug = triggerDebugApi;
        // 默认自动装配：triggerDebug=1 时无需手动 install()，场景就绪后直接监听 enter/exit。
        triggerDebugApi.install();
        console.log(
          '[trigger-debug] 已自动装配（triggerDebug=1）：直接走位即可观察 zone enter/exit；' +
            '注销执行 window.__triggerDebug.uninstall()，额外采样执行 .watch()',
        );
      }
    }
  },
);

onUnmounted(() => {
  // thirdroom input 收官：释放 H5 层自订阅句柄（在 sceneManager.dispose 之前，避免 subscribers 集合已释放二次 delete）
  inputUnsubscribes.value.forEach((unsub) => unsub());
  inputUnsubscribes.value = [];
  // 清理 inject 的 ctx 引用，避免子组件在卸载阶段访问已 dispose 的 EngineContext
  engineCtxRef.value = undefined;
  viewerSDK?.dispose();
});

// 监听路由 params / query 变化，任何参数改变时触发页面刷新（重新加载场景）
// 同时监听 route.params 和 route.query，覆盖地址栏直接修改 query 参数回车的场景：
//   例如将 ?showDebugViewer=false 改为 ?showDebugViewer=true 后回车，
//   vue-router 会感知到 query 变化并触发此 watch，进而执行 reload。
watch(
  () => JSON.stringify({ params: route.params, query: route.query }),
  (newVal, oldVal) => {
    if (newVal !== oldVal && oldVal !== undefined) {
      window.location.reload();
    }
  },
);

